module pulse_detect(
    input clk, rst_n, data_in,
    output reg data_out
);
// Design Implementation
localparam s0 = 2'b00, s1 = 2'b01, s2 = 2'b10, s3 = 2'b11;
reg [1:0] state, next_state;
always @ (*) begin
    case(state)
        s0: next_state = (data_in==1)?s0:s1;
        s1: next_state = (data_in==1)?s2:s1;
        s2: next_state = (data_in==1)?s0:s3;
        s3: next_state = (data_in==1)?s2:s1;
        default: next_state = s0;
    endcase
end
always @ (posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        state <= s0;
    end
    else begin
        state <= next_state;
    end
end
always @ (*) begin
    if((state == s2) && (data_in == 1'b0))
        data_out = 1'b1;
    else 
        data_out = 1'b0;
end

endmodule
